  "先连接钱包（顶部），再按 1 → 4 填完，点「生成 Karma 授权 SDK」，把结果交给你的 agent。每个子身份都有独立的凭据、订单和收支明细，全部挂在同一个主身份下。": "먼저 지갑을 연결하고(상단) 1 → 4를 채운 뒤 \"Karma 인가 SDK 생성\"을 눌러 결과를 agent에 넘기세요. 하위 ID마다 독립된 자격 증명, 주문, 수납 내역을 가지며 모두 같은 주체 ID 아래에 있습니다.",
