  "在单笔上限内自己发起委托；超了要你确认": "건당 한도 안에서는 스스로 위임을 시작하고, 초과하면 확인을 요청합니다",
  "在单笔最高之内：agent 可以自己挑商家、自己下单、自己收款，不用每次都问你；                 超过这个数，它会停下来等你在这个页面的「确认区」点一下。                 取消 / 退款 / 改价永远要你亲自确认。": "건당 최고 한도 안에서는 agent가 직접 판매자를 고르고 주문하고 대금을 받을 수 있으며 매번 확인을 요구하지 않습니다. 이 금액을 넘으면 agent는 멈춰서 이 페이지의 \"확인 구역\"에서 클릭을 기다립니다. 취소 / 환불 / 가격 변경은 항상 본인이 직접 확인해야 합니다.",
