  "把下面这一行原样写进你官网的这个地址（一个纯文本文件即可），然后回来点「回读校验」：": "아래 한 줄을 사이트의 이 경로에 그대로 넣고(일반 텍스트 파일 하나면 충분합니다) 돌아와서 \"다시 읽어 검증\"을 누르세요:",
  "把这份包交给 agent 运行时即可接入：环境变量 + 运行时密钥 + 自检命令。全程不涉及你的钱包私钥或助记词。": "이 패키지를 agent 런타임에 넘기면 연결됩니다: 환경 변수 + 런타임 키 + 자체 점검 명령. 지갑 개인키나 시드 문구는 전혀 관련되지 않습니다.",
