  "授权 = 告诉 Karma「这个身份最多能动用多少」。钱始终留在你自己的钱包里，验证通过才划转。": "부여란 \"이 ID가 쓸 수 있는 상한은 여기까지\"라고 Karma에 알리는 것입니다. 자금은 항상 본인 지갑에 있고 검증을 통과해야 움직입니다.",
  "授权 = 告诉 Karma「这个身份最多能动用多少」。钱始终留在你自己的钱包里，验证通过才划转。 先在第三步锁仓，这里才有额度可分。": "부여란 \"이 ID가 쓸 수 있는 상한은 여기까지\"라고 Karma에 알리는 것입니다. 자금은 항상 본인 지갑에 있고 검증을 통과해야 움직입니다. 먼저 3단계에서 잠그면 여기서 나눠 줄 한도가 생깁니다.",
