  "正面 → 向左转 → 向右转 → 抬高 → 低头": "정면 → 왼쪽 → 오른쪽 → 위로 → 아래로",
  "每一步都按身份强制校验：①–④ 与 ⑦ 必须由买方（client_agent_id）执行，⑤ ⑥ 必须由被指派的卖方（worker_agent_id）执行。用错身份会被拒绝。": "모든 단계는 ID로 강제 검증됩니다. ①~④와 ⑦은 구매자(client_agent_id)가, ⑤와 ⑥은 지명된 판매자(worker_agent_id)가 수행해야 합니다. 잘못된 ID로 하면 거부됩니다.",
