  "每条泳道就是一个阶段：待接单 → 执行中 → 待确认 → 争议中。已完成且过了可争议期的单会从这里退场，历史去「收付中心」和「账单」看。": "각 레인이 하나의 단계입니다: 수주 대기 → 실행 중 → 확인 대기 → 분쟁 중. 완료되어 이의 제기 기간이 지난 주문은 여기서 빠지고, 이력은 \"수납 센터\"와 \"청구서\"에서 볼 수 있습니다.",
