  "自动同步": "자동 동기화",
  "自己去找能办事的人 / 商家": "일을 해 줄 사람 / 판매자를 직접 찾기",
  "自检只读、不改状态：先看一遍机器能查的（信用代码校验位、邮箱 MX、官网控制权），再决定要不要提交。": "읽기 전용 자체 점검이며 상태를 바꾸지 않습니다. 먼저 기계가 확인할 수 있는 항목(신용 코드 검사 자릿수, 이메일 MX, 도메인 관리권)을 훑어본 뒤 제출할지 결정합니다.",
  "自检只读、不改状态：字号、经营者、经营范围、经营地址、联系邮箱先过一遍机器能查的。": "읽기 전용 자체 점검이며 상태를 바꾸지 않습니다. 상호, 사업자, 사업 범위, 사업장 주소, 연락 이메일을 먼저 기계로 확인합니다.",
  "自然人认证：这是「我本人是谁」。文件在你自己的浏览器里加密后才上传 —— Karma 只拿到密文和摘要，看不到证件内容，全程不碰你的私钥、助记词。": "자연인 인증은 \"내가 누구인가\"를 나타냅니다. 파일은 브라우저에서 암호화한 뒤에만 업로드되므로 Karma는 암호문과 다이제스트만 받고, 서류 내용도 개인키와 시드 문구도 보지 않습니다.",
  "至少一份营业执照": "사업자등록증 최소 1부",
  "营业执照": "사업자등록증",
  "营业执照必传；ICP 备案、数据来源授权、对公账户证明可选。每份文件单独加密上传，服务端只存摘要。": "사업자등록증은 필수이고 ICP 등록, 데이터 소스 인가, 법인 계좌 증명은 선택입니다. 각 파일은 개별로 암호화해 업로드하고 서버는 다이제스트만 저장합니다.",
  "营业执照必传；食品经营许可、特种行业许可、摊位证明可选。每份文件单独加密上传，服务端只存摘要与密文。": "사업자등록증은 필수이고 식품 영업 허가, 특수 업종 허가, 노점 증명은 선택입니다. 각 파일은 개별로 암호화해 업로드하고 서버는 다이제스트와 암호문만 저장합니다.",
  "营业执照（副本）": "사업자등록증(사본)",
