  "资金归属 · 为什么子身份不另开资金账户": "자금 귀속 · 하위 ID가 별도 자금 계정을 두지 않는 이유",
  "起步 · 3 步让 agent 跑起来": "시작하기 · 3단계로 agent 실행",
