  "），位置对了自动倒数拍摄。每一张都要和上一张有真实的姿态差 —— 拿同一张照片连拍、或对着屏幕翻拍会被当场拒掉。5 张采完你先过一眼，点「确认使用」才会采用。没有摄像头就逐张点「本角度改用照片」，或改用手机打开操作台。": "). 위치가 맞으면 자동으로 카운트다운 후 촬영합니다. 각 사진은 이전 사진과 실제 자세가 달라야 합니다. 같은 사진을 연사하거나 화면을 촬영하면 그 자리에서 거부됩니다. 5장을 찍으면 먼저 한 번 확인하고 \"사용 확정\"을 눌러야 적용됩니다. 카메라가 없으면 각 각도에서 \"사진 사용\"을 누르거나 휴대폰으로 콘솔을 여세요.",
