  "：所有子身份收到的钱都进主身份钱包（唯一收款地址）。": ": 하위 ID가 받은 모든 자금은 주체 지갑(유일한 수취 주소)으로 들어갑니다.",
  "：所有子身份的支出都从主身份钱包已锁仓、已授权的额度里出。": ": 하위 ID의 모든 지출은 주체 지갑의 잠긴·부여된 한도에서 나갑니다.",
  "：每笔都记在具体子身份名下，主身份是总账；切换子身份看到的收支明细互不混淆。": ": 각 건은 특정 하위 ID 명의로 기록되고 주체 ID가 총장부입니다. 하위 ID를 바꿔도 수납 내역은 섞이지 않습니다.",
