  "头向左转约 45°（露出侧脸），脸仍要留在圈里": "고개를 왼쪽으로 약 45° 돌리고(옆얼굴을 보여주고) 얼굴은 원 안에 유지하세요",
  "请向右转头": "고개를 오른쪽으로 돌려주세요",
  "头向右转约 45°（露出侧脸），脸仍要留在圈里": "고개를 오른쪽으로 약 45° 돌리고(옆얼굴을 보여주고) 얼굴은 원 안에 유지하세요",
  "请把头抬高一点": "고개를 조금 들어주세요",
  "脸慢慢抬高一点，额头和下巴都别出圈": "얼굴을 천천히 들어 올리세요. 이마와 턱 모두 원 밖으로 나가면 안 됩니다",
  "请把头低一点": "고개를 조금 숙여주세요",
  "下巴轻轻往下收一点，露出额头，脸别出圈": "턱을 살짝 당겨 이마가 보이게 하고 얼굴은 원 밖으로 나가지 않게 하세요",
  "摄像头还没有出画面": "카메라 화면이 아직 나오지 않았습니다",
  "读取文件失败": "파일을 읽지 못했습니다",
  "这不是一张能识别的图片": "인식할 수 있는 이미지가 아닙니다",
  "把脸放到圈中间": "얼굴을 원 가운데에 맞추세요",
  "再靠近一点，让脸占满圈": "조금 더 가까이 와서 얼굴로 원을 가득 채우세요",
  "退后一点，脸太大了": "조금 뒤로 물러나세요. 얼굴이 너무 큽니다",
  "头再抬一点，别切到上方": "고개를 조금 더 들어주세요. 위쪽이 잘렸습니다",
  "下巴也要在圈内": "턱도 원 안에 있어야 합니다",
  "位置合适，别动": "위치가 좋습니다. 움직이지 마세요",
  "刷脸认证": "얼굴 인증",
  "把脸放进圆圈里： 头顶和下巴都要在圈内 。照屏幕上的提示转头就行 —— 不用按键，系统会自己拍 。一共 正脸 + 左右侧脸 + 抬头低头 5 个角度 ，照片只留在这台设备上。": "얼굴을 원 안에 넣으세요: 정수리와 턱 모두 원 안에 있어야 합니다. 화면에 나오는 안내대로 고개만 돌리면 됩니다. 버튼을 누를 필요 없이 시스템이 알아서 촬영합니다. 각도는 총 5개: 정면 + 좌우 옆얼굴 + 위·아래. 사진은 이 기기에만 남습니다.",
  "这一张一直没采到 —— 也可以手动拍这一张，或点「本角度改用照片」。": "이 사진을 계속 캡처하지 못했습니다. 직접 촬영하거나 「이 각도는 사진 사용」을 누르세요.",
  "照提示动一下": "안내에 따라 조금 움직여 주세요",
  "请正对镜头，把脸放进圈里，然后停住别动": "카메라를 정면으로 보고 얼굴을 원 안에 넣은 뒤 그대로 멈춰 주세요",
  "照上面的提示转头就行 —— 停稳就会自动拍，不用按键。": "위 안내대로 고개만 돌리면 됩니다. 멈추면 자동으로 촬영되며 버튼은 필요 없습니다.",
  "准备好 —— 马上开始，把脸放进圈里。": "준비하세요 — 곧 시작합니다. 얼굴을 원 안에 넣으세요.",
  "很好，就这个角度 —— 稳住别动，马上自动拍。": "좋습니다, 바로 그 각도입니다. 그대로 멈춰 주세요. 곧 자동 촬영합니다.",
  "正在跟着你动…": "움직임을 따라가는 중…",
  "画面里一直有动静（背景里有人走动、或者镜头在晃）—— 稳住一下，也可以让镜头里只剩你一个人。": "화면에 계속 움직임이 있습니다 (배경에 지나가는 사람이 있거나 카메라가 흔들림). 잠시 안정시키고, 가능하면 화면에 본인만 나오게 해주세요.",
  "没抓到画面，再试一次": "화면을 가져오지 못했습니다. 다시 시도하세요",
  "光线太暗了，脸看不清 —— 换个亮点的地方再拍": "너무 어두워서 얼굴이 보이지 않습니다. 더 밝은 곳으로 가서 다시 촬영하세요",
  "画面太平了，看不出脸的轮廓 —— 别挡住镜头，把脸放进圈里再来": "화면이 너무 평평해 얼굴 윤곽이 보이지 않습니다. 카메라를 가리지 말고 얼굴을 원 안에 넣어 다시 해주세요",
  "这一张": "이 사진",
  "继续": "계속",
  "刚拍的人脸（正面）": "방금 촬영한 얼굴 (정면)",
  "对一下下面这几张（正脸 / 左 / 右 / 抬高 / 低头）：脸清楚没糊、是同一个人、每张角度都不一样。没问题就点「确认使用」。": "아래 사진들을 확인하세요 (정면 / 좌 / 우 / 위 / 아래): 얼굴이 선명하고 같은 사람이며 각도가 모두 달라야 합니다. 문제없으면 「사용 확정」을 누르세요.",
  "确认使用": "사용 확정",
