  "切换摄像头": "카메라 전환",
  "没反应？手动拍这一张": "반응이 없나요? 이 사진은 직접 촬영하세요",
  "打不开摄像头。": "카메라를 열 수 없습니다.",
  "这台设备上没有找到摄像头。": "이 기기에서 카메라를 찾지 못했습니다.",
  "摄像头被别的程序占着（会议软件、相机），关掉再试。": "카메라를 다른 앱(회의 소프트웨어, 카메라 앱)이 사용 중입니다. 닫고 다시 시도하세요.",
  "未绑定角色档案": "역할 프로필 미연결",
  "# ① 凭据自检：证明 API Key 有效（只有你自己能看到结果）": "# ① 자격 증명 자체 점검: API 키가 유효함을 확인합니다 (결과는 본인만 볼 수 있습니다)",
  "# ② 对端核验：任何人都能用，对方成交前会查这个": "# ② 상대방 검증: 누구나 실행할 수 있고, 상대방은 거래 전에 이를 확인합니다",
  "铸造本 agent 的运行时密钥": "이 agent의 런타임 키 발급",
  "读取已有密钥": "기존 키 불러오기",
