  "本次会话没有该 agent 的 API Key 明文（只在接入时返回一次）。可重新接入一个 agent，或把占位符替换成你当时保存的值。": "이 세션에는 해당 agent의 API 키 평문이 없습니다 (연결 시 한 번만 반환됩니다). agent를 다시 연결하거나 플레이스홀더를 저장해 둔 값으로 바꾸세요.",
