  "核验中…": "검증 중…",
  "P1 就绪：对端可以核验并成交": "P1 준비 완료: 상대방이 검증하고 거래할 수 있습니다",
  "见原始响应": "원본 응답 보기",
  "未检测到可用钱包，请先用右上角「连接钱包」认证": "사용 가능한 지갑이 감지되지 않았습니다. 먼저 오른쪽 위 「지갑 연결」로 인증하세요",
  "等待钱包签名…": "지갑 서명 대기 중…",
  "请先连接钱包完成认证": "먼저 지갑을 연결해 인증을 완료하세요",
  "读取自动授权策略…": "자동 승인 정책 불러오는 중…",
  "还没有保存自动授权策略。运行密钥的权限与限额必须与策略完全一致，请先到「设置」页点「保存授权策略」，再回来铸造。": "아직 자동 승인 정책이 저장되지 않았습니다. 런타임 키의 권한과 한도는 정책과 정확히 일치해야 합니다. 설정 페이지에서 「승인 정책 저장」을 누른 뒤 돌아와 발급하세요.",
  "读取 agent…": "agent 불러오는 중…",
  "这张身份卡名下没有找到该 agent": "이 ID 카드 명의에서 해당 agent를 찾지 못했습니다",
  "未接入": "미연결",
  "接入之后这里会变成一键官方核验（服务商核验通过即自动置位），不用人工等。": "연결하면 여기가 원클릭 공식 검증이 됩니다 (제공사 검증을 통과하면 자동으로 반영됩니다). 수동 검토를 기다릴 필요가 없습니다.",
  "未接入服务商": "제공사 미연결",
