  "(未知)": "(알 수 없음)",
  "把密钥补齐后刷新本页即可使用；在此之前仍可走下面的人工复核流程。": "키를 채우고 이 페이지를 새로 고치면 사용할 수 있습니다. 그전까지는 아래 수동 심사 절차를 이용할 수 있습니다.",
  "服务商未配置完成": "제공사 설정이 완료되지 않았습니다",
  "做完之后回到本页点「我已做完，查结果」；页面也会自动查。": "완료한 뒤 이 페이지로 돌아와 「완료했습니다, 결과 확인」을 누르세요. 페이지가 자동으로 확인하기도 합니다.",
  "做完之后回到本页，服务商会把结果回调给 Karma，页面会自动更新。": "완료한 뒤 이 페이지로 돌아오세요. 제공사가 결과를 Karma로 콜백하면 페이지가 자동으로 갱신됩니다.",
  "可以开始": "시작할 수 있습니다",
  "服务商核验通过 —— 主身份已激活": "제공사 검증을 통과했습니다 — 주 ID가 활성화되었습니다",
  "未通过": "통과하지 못함",
  "这条身份已经是通过状态": "이 ID는 이미 통과 상태입니다",
  "服务商还在处理，稍后自动再查一次…": "제공사가 아직 처리 중입니다. 잠시 후 자동으로 다시 확인합니다…",
