  "当前只显示子身份 {0}… 的记录：共 {1} 条，已隐藏 {2} 条属于其它子身份/主体身份的记录；顶部「切换子身份」选「主体（全部）」可查看全部。": "하위 ID {0}… 의 기록만 표시 중: 총 {1}건, {2}건은 다른 하위 ID/주체 ID의 기록이라 숨김. 상단 「하위 ID 전환」에서 「주체(전체)」를 선택하면 모두 볼 수 있습니다.",
