  "结算被拦住：这条任务还没有「成功的执行回执」。\n执行回执必须由卖方 agent 用它自己的运行密钥（Ed25519）签名后提交到 /v1/receipts，Karma 会校验签名与哈希，操作台只能查询、不能代签。\n先让卖方 agent 提交回执（本页「回执证明」可查到），再回到这里批准结算。": "정산이 차단되었습니다: 이 작업에는 아직 「성공한 실행 영수증」이 없습니다.\n영수증은 판매자 agent가 자신의 런타임 키(Ed25519)로 서명해 /v1/receipts에 제출해야 합니다. Karma가 서명과 해시를 검증하며, 운영 콘솔은 조회만 가능하고 대신 서명할 수 없습니다.\n먼저 판매자 agent가 영수증을 제출하게 한 뒤(이 페이지 「영수증 증명」에서 확인 가능) 여기로 돌아와 정산을 승인하세요.",
