  "边界不完整：对端可见缺口。建议走 connect-from-template 补齐 service_specs 与不做清单。": "경계가 불완전합니다: 상대방에게 격차가 보입니다. connect-from-template 으로 service_specs 와 하지 않을 목록을 보완하세요.",
  "交付与证据责任在本 agent；资金不托管；转委托默认关闭；成交字段另走 Important Fields 三方锁定。": "납품과 증빙 책임은 이 agent 에 있습니다. 자금은 보관하지 않습니다. 재위임은 기본적으로 꺼져 있습니다. 거래 필드는 Important Fields 3자 잠금으로 진행합니다.",
  "用 agent 私钥对 canonical_message 做 Ed25519 签名，填入 ownership_proof": "agent 개인키로 canonical_message 에 Ed25519 서명해 ownership_proof 에 넣습니다",
  "已写入目录。若 p1_ready=false，对端核验将拒绝将其视为可履约商家；请走 connect-from-template 补齐身份/责任/履约能力。": "디렉터리에 기록했습니다. p1_ready=false 이면 상대방 검증에서 이행 가능한 판매자로 보지 않습니다. connect-from-template 으로 신원·책임·이행 역량을 보완하세요.",
