  "一键接入完成：已按垂直场景落库身份/边界/责任签认，并签发引导 API Key（仅此一次明文）。": "원클릭 연결이 완료되었습니다: 버티컬별 신원·경계·책임 서명을 등록하고 초기 API Key 를 발급했습니다(평문은 이번 한 번만).",
  "接入完成：身份卡 → agent 已绑定，责任签认与履约边界已落库。": "연결이 완료되었습니다: 신원 카드 → agent 를 바인딩하고 책임 서명과 이행 경계를 등록했습니다.",
  "agent 已停用；Karma 托管的运行密钥已销毁，API Key 不再可通过鉴权。": "agent 가 비활성화되었습니다. Karma 가 보관하던 실행 키는 폐기되었고 API Key 는 더 이상 인증을 통과하지 못합니다.",
  "公开侧为聚合与承诺哈希；明细金额/身份仅密文可查": "공개 측은 집계와 커밋먼트 해시만 제공합니다. 명세 금액·신원은 암호문으로만 확인할 수 있습니다",
  "公开字段仅为承诺哈希与场景/结果；金额与当事人身份在 karma2 密文中，持 parties/regulator 角色密钥可解密审计": "공개 필드는 커밋먼트 해시와 시나리오·결과뿐입니다. 금액과 당사자 신원은 karma2 암호문에 있으며, parties/regulator 역할 키 보유자가 복호화해 감사할 수 있습니다",
  "公开可核验承诺完整性；不含金额明文": "커밋먼트 무결성은 공개 검증 가능합니다. 금액 평문은 포함하지 않습니다",
  "解密仅供当事人或监管审计；禁止将明文写入公开索引": "복호화는 당사자 또는 규제 감사에만 사용합니다. 평문을 공개 인덱스에 기록하는 것은 금지됩니다",
  "Agent 可在验真通过后代用户完成结算确认，节省时间": "검증이 통과되면 Agent 가 사용자를 대신해 정산 확인을 완료할 수 있어 시간을 절약합니다",
  "本场景要求主人显式确认或验真未完成，禁止 Agent 代结算": "이 시나리오는 오너의 명시적 확인이 필요하거나 검증이 완료되지 않았습니다. Agent 가 대신 정산할 수 없습니다",
  "卖方确认接单后违约赔偿责任生效；责任金 {0} bps，补偿 {1} bps": "판매자가 수주를 확인하면 위약 배상 책임이 발효됩니다. 책임금 {0} bps, 보상 {1} bps",
  "卖方确认接单后违约赔偿责任生效；责任金 {0} bps，补偿 {1} bps（未确认档位乘数 ×{2}）": "판매자가 수주를 확인하면 위약 배상 책임이 발효됩니다. 책임금 {0} bps, 보상 {1} bps(미확인 등급 배수 ×{2})",
  "可重新发现匹配其他商家": "다시 탐색해 다른 판매자를 찾을 수 있습니다",
