  "本次意向已因卖方超时取消；请重新发现匹配": "판매자 시간 초과로 이 의향이 취소되었습니다. 다시 탐색해 주세요",
  "卖方边界未通过 P2 核验：未声明场景、确认策略被放宽、或 P1 未就绪。安全优先，拒绝履约。": "판매자 경계가 P2 검증을 통과하지 못했습니다: 시나리오 미신고, 확인 정책 완화, 또는 P1 미준비입니다. 안전 우선으로 이행을 거부합니다.",
