  "物流拒收：交付物与锁定字段不一致；错件损失共担": "물류가 수령을 거부했습니다: 납품물이 잠긴 필드와 일치하지 않습니다. 오배송 손실은 분담합니다",
  "物流已送达并上传防伪凭证；买方需在 {0}s 内确认，超时且链路正确则默认确认": "물류가 배송되고 위조 방지 증빙이 업로드되었습니다. 구매자는 {0}s 안에 확인해야 하며, 초과 시 체인이 정상이면 기본 확인으로 처리됩니다",
  "验真未完成，缺少: {0}": "검증이 완료되지 않았습니다. 누락: {0}",
  "交付验真通过（对照锁定字段）": "납품 검증을 통과했습니다(잠긴 필드와 대조)",
  "数字/行程场景验真通过": "디지털·여정 시나리오 검증을 통과했습니다",
  "静默窗已过但链路未通过: {0} — 不默认确认": "무응답 기간이 지났지만 체인이 통과하지 못했습니다: {0} — 기본 확인하지 않습니다",
  "买方超时未确认；已校验卖方发出+物流接件/送达凭证正确 → 默认确认": "구매자가 기한 내 확인하지 않았습니다. 판매자 발송과 물류 수령·배송 증빙이 정상임을 검증 → 기본 확인 처리",
  "使用全局默认确认策略（未知 scene，勿用于高风险成交）": "전역 기본 확인 정책을 사용합니다(알 수 없는 scene. 고위험 거래에는 사용하지 마세요)",
  "需主人确认 {0} 步；可自动 {1} 步。Agent 只需在必须确认点询问是否确认。": "오너 확인이 필요한 단계는 {0}개, 자동 실행 가능한 단계는 {1}개입니다. Agent 는 필수 확인 지점에서만 묻습니다.",
  "主人已确认，Agent 可继续接单/锁字段/执行/结算": "오너가 확인했습니다. Agent 는 수주·필드 잠금·실행·정산을 계속할 수 있습니다",
  "主人已拒绝，停止该步，不接单、不锁款": "오너가 거부했습니다. 이 단계에서 멈추고 수주도 자금 잠금도 하지 않습니다",
  "主身份本人实名认证：证件 + 刷脸": "주 신원 본인 실명 인증: 신분증 + 얼굴 인증",
  "已激活：信誉记录从现在开始记，可以接单、可以被撮合。": "활성화됨: 평판 기록이 지금부터 시작되며, 수주와 매칭이 가능합니다.",
  "未激活：主身份本人完成「证件 + 刷脸」认证后自动激活，信誉记录才会开始记；未激活期间可以锁仓、可以给身份划额度，但不能接单、不能被撮合。": "비활성: 주 신원 본인이 「신분증 + 얼굴 인증」을 완료하면 자동으로 활성화되고 평판 기록이 시작됩니다. 비활성 기간에는 잠금과 한도 배정은 가능하지만 수주와 매칭은 할 수 없습니다.",
  "requires master identity verification (证件 + 刷脸). 主身份完成实名认证后自动激活。": "requires master identity verification(신분증 + 얼굴 인증). 주 신원 실명 인증이 완료되면 자동으로 활성화됩니다.",
  "本人确认对该 agent 的交付与证据责任边界负责；资金不托管；未声明能力不接单；虚假指标视为违约。": "본인이 이 agent 의 납품과 증빙 책임 경계에 책임이 있음을 확인합니다. 자금은 보관하지 않습니다. 미신고 역량으로는 수주하지 않습니다. 허위 지표는 위약으로 봅니다.",
  "P1 就绪：身份/责任/履约能力已界定且可对端核验，可安全进入发现与成交。": "P1 준비 완료: 신원·책임·이행 역량이 정의되었고 상대방이 검증할 수 있습니다. 안전하게 탐색과 거래로 진입할 수 있습니다.",
  "P1 未就绪：存在 gaps，对端不应将其视为可履约商家/企业（用户亦应补齐绑定）。": "P1 미준비: gap 이 있어 상대방은 이를 이행 가능한 판매자·기업으로 보아서는 안 됩니다(사용자도 바인딩을 보완해야 합니다).",
  "核验基于目录行、名片、边界哈希、责任签认与信誉记录；boundary_complete 与 ack 均不可仅靠客户端自报。": "검증은 디렉터리 행, 명함, 경계 해시, 책임 서명, 평판 기록에 기반합니다. boundary_complete 와 ack 는 클라이언트 자기 신고만으로는 인정되지 않습니다.",
  "配对接入": "페어링",
  "配对码接入": "페어링 코드로 연결",
  "agent 发起接入时会拿到一串配对码，把它给你；你在这里确认一次，它自己把凭据领走。你不用把密钥抄给它，它也不该向你要密钥。": "에이전트가 연결을 시작하면 페어링 코드가 발급되어 사용자에게 보여 줍니다. 여기서 한 번만 확인하면 자격 증명은 에이전트가 직접 받아 갑니다. 키를 적어서 넘겨줄 필요도, 에이전트가 키를 요구할 일도 없습니다.",
  "配对码": "페어링 코드",
  "查询请求": "요청 조회",
  "查询中…": "조회 중…",
  "批准接入": "연결 승인",
  "已批准接入": "연결이 승인되었습니다",
  "API Key 已经放进这次配对，等它自己来领（只发一次，本页不会显示这串密钥）。": "API 키는 이 페어링에 담아 두었고 에이전트가 직접 받아 갑니다. 한 번만 전달되며 이 페이지에는 키가 표시되지 않습니다.",
  "授权额度（可选）": "한도 부여(선택)",
  "批准之后 agent 只有身份、还动不了钱。在这里划一次额度并签名，钱钥匙会跟身份一起交给它。": "승인 직후에는 에이전트가 신원만 있고 자금을 움직일 수 없습니다. 여기서 한도를 정하고 한 번 서명하면 자금 키가 신원과 함께 전달됩니다.",
