  "agent 用配对码领取时会一次拿到身份钥匙和钱钥匙，本页不显示密钥。": "에이전트가 페어링 코드로 수령하면 신원 키와 자금 키를 한 번에 받습니다. 이 페이지에는 키가 표시되지 않습니다.",
  "等待你批准": "승인 대기 중",
