  "先把 agent 给你的配对码填进来": "먼저 에이전트가 준 페어링 코드를 입력하세요",
  "这条请求已处理": "이미 처리된 요청입니다",
  "批准中…": "승인 중…",
  "至少勾一项权限": "권한을 최소 하나 선택하세요",
  "单笔和每日上限都要大于 0": "건당 한도와 일일 한도는 모두 0보다 커야 합니다",
