  "签名工具未加载，请刷新页面": "서명 도구가 로드되지 않았습니다. 페이지를 새로고침하세요",
  "③ 放进交付，等 agent 来领…": "③ 전달 항목에 넣고 에이전트 수령을 기다리는 중…",
