  "移除": "제거",
  "认证状态": "인증 상태",
  "账户状态": "계정 상태",
  "钱包（脱敏）": "지갑(마스킹)",
  "这张身份卡是你在 Karma 的通行证：认证一次即可出示给任意接入 Karma 的 agent 基础设施，用于收付验证与结算。卡内不含私钥、助记词或完整钱包地址。": "이 신원 카드는 Karma의 통행증입니다. 한 번 인증하면 Karma에 연결된 어떤 agent 인프라에도 제시할 수 있고, 수금·지급 검증과 결제에 쓰입니다. 카드에는 개인키, 시드 구문, 전체 지갑 주소가 들어 있지 않습니다.",
  "本 agent 的运行时密钥（只显示这一次，请立即连同上面的 env 一起保存）": "이 agent의 런타임 키(이번 한 번만 표시됩니다. 위 env와 함께 지금 저장하세요)",
  "运行时密钥用于 agent 服务器向 Karma 请求付款码 / 提交回执 / 申请结算。": "런타임 키는 agent 서버가 Karma에 결제 코드 요청, 영수증 제출, 정산 신청을 할 때 사용합니다.",
  "它绑定的权限与限额必须与「设置」页保存的自动授权策略完全一致，所以先保存策略再铸造。": "여기에 묶이는 권한과 한도는 「설정」 페이지에 저장한 자동 승인 정책과 정확히 일치해야 합니다. 그러니 정책을 먼저 저장한 뒤 발급하세요.",
  "② 运行时密钥（绑定本 agent）": "② 런타임 키(이 agent에 바인딩)",
