  "④ 交付说明": "④ 인계 안내",
  "把上面的 env 写进 agent 运行时的环境变量（或直接下载文件）。": "위 env를 agent 런타임의 환경 변수에 넣으세요(파일을 바로 내려받아도 됩니다).",
  "agent 用 KARMA_AGENT_ID + KARMA_API_KEY 完成身份识别；用 KARMA_RUNTIME_KEY 请求付款码、提交回执、申请结算。": "agent는 KARMA_AGENT_ID + KARMA_API_KEY로 신원을 밝히고, KARMA_RUNTIME_KEY로 결제 코드 요청·영수증 제출·정산 신청을 합니다.",
  "对方成交前会查 p1-status；这就是 Karma 对这笔收付的验证依据。": "상대방은 거래 성사 전에 p1-status를 확인합니다. 이것이 Karma가 이 수금·지급을 검증하는 근거입니다.",
  "不再需要这个 agent 时，用下面「停用并销毁密钥」——Karma 托管的运行密钥会一并销毁。": "이 agent가 더 필요 없으면 아래 「비활성화하고 키 폐기」를 사용하세요. Karma가 보관하는 런타임 키도 함께 폐기됩니다.",
  "这个身份还打不开复核队列：队列只对复核岗（verifier）开放。": "이 신원으로는 아직 검수 큐를 열 수 없습니다. 큐는 검수 담당(verifier)에게만 열려 있습니다.",
  "复核岗不能自助开通 —— 需要运维先把身份加进": "검수 담당은 스스로 개설할 수 없습니다. 먼저 운영 담당이 신원을 다음에 추가해야 합니다:",
  "，再由本人建一张 verifier 类身份档案。": "그다음 본인이 verifier 유형의 신원 프로필을 만들면 됩니다.",
  "链上锁仓未启用：当前锁仓走台账模式，没有真实 USDC 进入合约。": "온체인 잠금이 활성화되지 않았습니다. 현재 잠금은 원장 모드로 동작하며 실제 USDC가 컨트랙트로 들어가지 않습니다.",
